import torch
import tilelang as T
from tilelang.jit import compile
import numpy as np

@T.prim_func
def mean_reduction_kernel(
    A: T.Buffer((128, 4096, 4095), "float16"),
    B: T.Buffer((128, 4095), "float16")
):
    # Initialize shared memory for reduction
    shared_mem = T.alloc_shared((32, 4095), "float16")

    # Thread and block indices
    tx = T.thread_binding(0, 32, "threadIdx.x")
    ty = T.thread_binding(0, 128, "threadIdx.y")
    bx = T.thread_binding(0, 128, "blockIdx.x")

    # Load data into shared memory
    for i in T.serial(0, 128):
        if i < 4096:
            shared_mem[tx, i] = A[bx, i, ty]

    # Synchronize threads
    T.evaluate(T.call_extern("semaphore_wait", 0))

    # Perform reduction
    for i in T.serial(0, 128):
        if i < 4096:
            if tx == 0:
                B[bx, ty] += shared_mem[tx, i]

    # Finalize reduction
    if tx == 0:
        for i in T.serial(0, 128):
            B[bx, ty] = B[bx, ty] / 4096.0

class ModelNew(torch.nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.kernel = compile(mean_reduction_kernel, target="cuda")

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Create output tensor with correct shape
        output_shape = list(x.shape)
        output_shape.pop(self.dim)
        output = torch.empty(output_shape, dtype=torch.float16, device=x.device)

        # Launch kernel
        self.kernel(x, output)
        return output

